script:
// Client Script: "diagram image gallery"  —  Quality Inspection (Form)
// Renders an image gallery inside the Image field `custom_diagram`.
//
// Wrapped in an IIFE so its helpers can't collide with other Client Scripts
// on this doctype — Frappe evals every Client Script for a doctype in one
// shared scope.
//
// Note: `custom_diagram` is an Image field. Frappe's ControlImage keeps drawing
// its own placeholder into an inner $body; we replace the wrapper's content,
// so that placeholder is detached and never shows. An HTML field works the same.

(function () {
	"use strict";

	const GALLERY_FIELD = "custom_diagram";
	const IMAGE_RE = /\.(jpe?g|png|gif|webp)$/i;

	// Untagged files = sidebar paperclip uploads or anything added before this
	// script. Set to true if you want those images shown here as well.
	const CLAIMS_UNTAGGED = false;

	// Quality Inspection is submittable. Set to true to block upload/delete
	// once the inspection is submitted (cancelled is always locked).
	const LOCK_AFTER_SUBMIT = false;

	frappe.ui.form.on("Quality Inspection", {
		refresh(frm) {
			render(frm);
		},
	});

	function can_edit(frm) {
		if (frm.doc.docstatus === 2) return false;
		if (LOCK_AFTER_SUBMIT && frm.doc.docstatus === 1) return false;
		return true;
	}

	function render(frm) {
		const field = frm.fields_dict[GALLERY_FIELD];
		if (!field) return;

		const editable = can_edit(frm);

		// margin-left:auto pins the button right whether or not a heading
		// sits beside it.
		field.$wrapper.html(`
			<div class="image-gallery-container">
				<div style="display:flex;align-items:center;margin-bottom:15px;">
					<span style="font-weight:600;">${__("Diagrams")}</span>
					<button class="btn btn-primary btn-sm upload-images-btn"
							style="margin-left:auto;">
						<i class="fa fa-upload"></i> ${__("Upload images")}
					</button>
				</div>
				<div class="image-gallery"
					 style="display:grid;
							grid-template-columns:repeat(auto-fill, minmax(150px, 1fr));
							gap:15px;"></div>
			</div>
		`);

		const gallery = field.$wrapper.find(".image-gallery");
		const $btn = field.$wrapper.find(".upload-images-btn");

		// Unsaved document: no name to attach a File record to.
		if (frm.is_new()) {
			$btn.prop("disabled", true);
			gallery.html(empty_state(__("Save the inspection before uploading images.")));
			return;
		}

		if (editable) {
			$btn.on("click", () => open_uploader(frm));
		} else {
			$btn.hide();
		}

		gallery.html(empty_state(__("Loading…")));
		fetch_images(frm).then((files) => paint(frm, gallery, files, editable));
	}

	function fetch_images(frm) {
		// docinfo.attachments omits attached_to_field, so it can't tell which
		// field a file was uploaded for. Query the File records directly.
		return frappe.db
			.get_list("File", {
				filters: {
					attached_to_doctype: frm.doctype,
					attached_to_name: frm.doc.name,
				},
				fields: ["name", "file_name", "file_url", "attached_to_field"],
				limit: 0,
				order_by: "creation asc",
			})
			.then((files) => (files || []).filter(belongs_here))
			.catch(() => []);
	}

	function belongs_here(file) {
		if (!IMAGE_RE.test(file.file_name || file.file_url || "")) return false;

		const tag = file.attached_to_field;
		if (tag === GALLERY_FIELD) return true;
		if (!tag) return CLAIMS_UNTAGGED;
		return false; // tagged for some other field
	}

	function open_uploader(frm) {
		// doctype/docname/fieldname make FileUploader create AND attach the
		// File itself, tagged with attached_to_field. Don't insert a second one.
		let pending = null;

		new frappe.ui.FileUploader({
			doctype: frm.doctype,
			docname: frm.doc.name,
			fieldname: GALLERY_FIELD,
			folder: "Home/Attachments",
			allow_multiple: true,
			restrictions: {
				allowed_file_types: [".jpg", ".jpeg", ".png", ".webp", ".gif"],
			},
			on_success() {
				// Fires once per file with allow_multiple — debounce so a batch
				// repaints once instead of once per image.
				clearTimeout(pending);
				pending = setTimeout(() => {
					render(frm);
					frappe.show_alert({
						message: __("Images uploaded"),
						indicator: "green",
					});
				}, 400);
			},
		});
	}

	function paint(frm, gallery, images, editable) {
		gallery.empty();

		if (!images.length) {
			gallery.html(
				empty_state(
					editable
						? __("No images yet. Upload one to get started.")
						: __("No images.")
				)
			);
			return;
		}

		images.forEach((file) => {
			const safe_name = frappe.utils.escape_html(file.file_name || "");
			const safe_url = frappe.utils.escape_html(file.file_url || "");

			const delete_btn = editable
				? `<button class="btn btn-xs btn-danger delete-image"
						   title="${__("Delete")}">
						<i class="fa fa-trash"></i>
				   </button>`
				: "";

			const card = $(`
				<div style="position:relative;border:1px solid #ddd;
							border-radius:10px;overflow:hidden;background:white;">
					<img src="${safe_url}" alt="${safe_name}"
						 style="width:100%;height:150px;object-fit:cover;
								cursor:pointer;display:block;">
					<div style="padding:8px;display:flex;
								justify-content:space-between;align-items:center;">
						<span style="font-size:12px;overflow:hidden;
									 text-overflow:ellipsis;white-space:nowrap;
									 max-width:110px;"
							  title="${safe_name}">${safe_name}</span>
						${delete_btn}
					</div>
				</div>
			`);

			card.find("img").on("click", () => window.open(file.file_url, "_blank"));

			card.find(".delete-image").on("click", () => {
				frappe.confirm(__("Delete this image?"), () => {
					frappe.db
						.delete_doc("File", file.name)
						.then(() => {
							render(frm);
							frappe.show_alert({
								message: __("Image deleted"),
								indicator: "green",
							});
						})
						.catch(() => {
							frappe.show_alert({
								message: __("Could not delete image"),
								indicator: "red",
							});
						});
				});
			});

			gallery.append(card);
		});
	}

	function empty_state(text) {
		return `
			<div class="text-muted" style="padding:30px;text-align:center;
				 border:1px dashed #ccc;border-radius:8px;grid-column:1/-1;">
				${text}
			</div>
		`;
	}
})();
